//! 📦️ Canonical History indexes retain original native records in separately paid first-party pages.
use super::RetainedHistoryRecordsStep;
use semio_framework_value::{list::{PagedList,PagedListError},ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress};
use std::mem::ManuallyDrop;
pub struct RetainedHistoryPagedRecords<T>{records:ManuallyDrop<PagedList<T,{usize::MAX}>>,maximum_records:usize,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>,closed:bool}
fn error(error:PagedListError)->ValueError{ValueError::literal(match error.kind{semio_framework_value::list::PagedListRefusalKind::OwnershipLimit=>ValueRefusalKind::OwnershipLimit,semio_framework_value::list::PagedListRefusalKind::AllocationFailed=>ValueRefusalKind::AllocationFailed,semio_framework_value::list::PagedListRefusalKind::InvariantViolated=>ValueRefusalKind::InvariantViolated},error.reason)}
impl<T> RetainedHistoryPagedRecords<T>{
 pub fn admit(maximum_records:usize,g:RetainedCloneGrant)->Result<Option<Self>,ValueError>{if maximum_records==0{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original paged History index bound is absent"))}if g.maximum_items==0||g.maximum_depth==0{return Ok(None)}Ok(Some(Self{records:ManuallyDrop::new(PagedList::empty()),maximum_records,receipt:Some((g,RetainedCloneProgress{copied_items:1,..Default::default()})),closed:false}))}
 pub fn receipt(&self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt}
 pub fn take_receipt(&mut self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt.take()}
 pub fn records(&self)->&PagedList<T,{usize::MAX}>{&self.records}
 pub fn demands(&self)->Result<RetirementDemand,ValueError>{if self.closed||self.receipt.is_some(){return Ok(Default::default())}if self.records.len()>=self.maximum_records{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original paged History index exceeds declared record bound"))}if self.records.has_reserved_slot(){return Ok(RetirementDemand{depth:self.records.next_push_depth_demand().map_err(error)?,..Default::default()})}Ok(RetirementDemand{copy_bytes:self.records.next_reserve_copy_byte_demand().map_err(error)?,capacity_bytes:self.records.next_allocation_bytes().map_err(error)?,depth:self.records.next_reserve_depth_demand().map_err(error)?,..Default::default()})}
 fn publish(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.receipt=Some((g,p));if !p.fits(g){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original paged History receipt exceeded caller grant").with_retained_progress(p))}Ok(())}
 pub fn append_original(&mut self,original:&mut Option<T>,g:RetainedCloneGrant)->Result<RetainedHistoryRecordsStep,ValueError>{if original.is_none()||self.closed||self.receipt.is_some(){return Ok(RetainedHistoryRecordsStep::Blocked)}let d=self.demands()?;if g.maximum_items==0||g.maximum_depth<d.depth||g.maximum_copy_bytes<d.copy_bytes||g.maximum_capacity_bytes<d.capacity_bytes||g.maximum_release_bytes<d.release_bytes{return Ok(RetainedHistoryRecordsStep::Blocked)}if !self.records.has_reserved_slot(){match self.records.reserve_one_funded(g){Ok(p)=>{self.publish(g,p)?;return Ok(RetainedHistoryRecordsStep::Reserved)},Err(refusal)=>{let p=RetainedCloneProgress{copied_items:usize::from(refusal.allocated_bytes!=0),retained_capacity_bytes:refusal.allocated_bytes,..Default::default()};self.publish(g,p)?;return Err(error(refusal.refusal()).with_retained_progress(p))}}}let value=original.take().unwrap();if let Err(value)=self.records.push_reserved(value){*original=Some(value);return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original paged History reserved slot was refused"))}self.publish(g,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistoryRecordsStep::Published)}
 pub fn take_ready_into(&mut self,recipient:&mut Option<PagedList<T,{usize::MAX}>>,g:RetainedCloneGrant)->Result<RetainedHistoryRecordsStep,ValueError>{if self.closed||self.receipt.is_some()||recipient.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(RetainedHistoryRecordsStep::Blocked)}*recipient=Some(std::mem::replace(&mut*self.records,PagedList::empty()));self.closed=true;self.publish(g,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistoryRecordsStep::Closed)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.records.terminal_is_empty()&&self.receipt.is_none()}
}
impl<T> Drop for RetainedHistoryPagedRecords<T>{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original paged History index abandoned native records");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.records)}}}}
